<?php
declare(strict_types=1);require __DIR__.'/_auth.php';$actor=$auth->requireLogin();$auth->requireRole('ADMIN');$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$user=$id?$auth->users()->find($id):null;if($id&&!$user){http_response_code(404);exit('User not found');}$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$username=trim((string)($_POST['username']??''));$fullName=trim((string)($_POST['full_name']??''));$roles=array_values(array_intersect(DecisionRules\UserRepository::ROLES,(array)($_POST['roles']??[])));$active=isset($_POST['active']);if(!preg_match('/^[A-Za-z0-9_.-]{3,64}$/',$username))$errors[]='Username must contain 3–64 letters, numbers, dots, underscores, or hyphens.';if($fullName===''||strlen($fullName)>191)$errors[]='Full name is required.';if(!$roles)$errors[]='Select at least one role.';$password=(string)($_POST['temporary_password']??'');if(!$id&&strlen($password)<12)$errors[]='Temporary password must be at least 12 characters.';if(!$errors){try{if($id){$old=$user['roles'];$auth->users()->update($id,$fullName,$active,$roles);$auth->audit()->log('USER_UPDATED',$actor['id'],$actor['username'],'USER',$id);if($old!==$roles)$auth->audit()->log('USER_ROLES_CHANGED',$actor['id'],$actor['username'],'USER',$id,['roles'=>$roles]);}else{$id=$auth->users()->create(compact('username','fullName','password','roles','active')+['full_name'=>$fullName]);$auth->audit()->log('USER_CREATED',$actor['id'],$actor['username'],'USER',$id,['username'=>$username,'roles'=>$roles]);}$_SESSION['flash']='User saved.';redirect('users.php');}catch(Throwable $e){$errors[]='Unable to save user. The username may already exist.';}}$user=['id'=>$id,'username'=>$username,'full_name'=>$fullName,'roles'=>$roles,'active'=>$active];}
$user??=['id'=>null,'username'=>'','full_name'=>'','roles'=>['VIEWER'],'active'=>true];$title=$id?'Edit User':'Create User';$activePage='users';require __DIR__.'/partials/header.php';?>
<?php foreach($errors as $error):?><div class="alert error"><?=e($error)?></div><?php endforeach;?><form method="post" class="panel form-section"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><?php if($id):?><input type="hidden" name="id" value="<?=(int)$id?>"><?php endif;?><div class="form-grid"><label>Username<input name="username" value="<?=e($user['username'])?>" <?=$id?'readonly':''?> required></label><label>Full Name<input name="full_name" value="<?=e($user['full_name'])?>" required></label><?php if(!$id):?><label class="full">Temporary Password<input type="password" name="temporary_password" minlength="12" required autocomplete="new-password"></label><?php endif;?><fieldset class="full role-field"><legend>Roles</legend><?php foreach(DecisionRules\UserRepository::ROLES as $role):?><label class="check"><input type="checkbox" name="roles[]" value="<?=e($role)?>" <?=in_array($role,$user['roles'],true)?'checked':''?>><span><?=e(str_replace('_',' ',$role))?></span></label><?php endforeach;?></fieldset><label class="check full"><input type="checkbox" name="active" <?=$user['active']?'checked':''?>><span>Active</span></label></div><div class="form-actions form-pad"><a class="btn secondary" href="users.php">Cancel</a><button class="btn primary">Save User</button></div></form><?php require __DIR__.'/partials/footer.php';?>
